export function parseCsv(text) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  if (text === '') return [];

  const records = [];
  let record = [];
  let field = '';
  let i = 0;

  const atTerminator = () => text[i] === '\n' || (text[i] === '\r' && text[i + 1] === '\n');

  for (;;) {
    if (text[i] === '"') {
      i += 1;
      for (;;) {
        if (i >= text.length) throw new SyntaxError('a quoted field never closed');
        if (text[i] === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
            continue;
          }
          i += 1;
          break;
        }
        field += text[i];
        i += 1;
      }
      if (i < text.length && text[i] !== ',' && !atTerminator()) {
        throw new SyntaxError('a closing quote must be followed by a comma or a terminator');
      }
    } else {
      while (i < text.length && text[i] !== ',' && !atTerminator()) {
        field += text[i];
        i += 1;
      }
    }

    if (i >= text.length) {
      record.push(field);
      records.push(record);
      break;
    }
    if (text[i] === ',') {
      record.push(field);
      field = '';
      i += 1;
      continue;
    }
    record.push(field);
    field = '';
    records.push(record);
    record = [];
    i += text[i] === '\r' ? 2 : 1;
    if (i >= text.length) break;
  }

  return records;
}
